function OrderModal({boot,user,close,saved}:{boot:Bootstrap;user:User;close:()=>void;saved:()=>void}){const[inst,setInst]=useState(user.role==='KURUM'?user.institution_id||'':boot.institutions[0]?.id||''),[exam,setExam]=useState(''),[qty,setQty]=useState(''),[price,setPrice]=useState('');const exams=useAsync(()=>api(`/api/exams?season_id=${boot.seasons.find(s=>s.is_active)?.id||''}&active=1`),[]);const availableInstitutions=user.role==='PERSONEL'?boot.institutions.filter(i=>i.staff_id===user.id):boot.institutions;return <Modal title="Sipariş oluştur ve onayla" close={close}><FormGrid>{user.role!=='KURUM'&&<Field label="Kurum"><select value={inst} onChange={e=>setInst(e.target.value)}>{availableInstitutions.map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select></Field>}<Field label="Sınav"><select value={exam} onChange={e=>setExam(e.target.value)}><option value="">Seçiniz</option>{((exams.data as any)?.items||[]).map((x:any)=><option key={x.id} value={x.id}>{x.grade_name} · {x.publisher_short} · {x.name}</option>)}</select></Field><Field label="Adet"><input type="number" value={qty} onChange={e=>setQty(e.target.value)}/></Field><Field label="Birim fiyat (TL, boşsa varsayılan)"><input type="number" value={price} onChange={e=>setPrice(e.target.value)}/></Field></FormGrid><ModalActions close={close} save={async()=>{await api('/api/orders',{method:'POST',body:JSON.stringify({institution_id:inst,exam_id:exam,quantity:Number(qty),unit_price:price?Math.round(Number(price)*100):undefined})});saved()}}/></Modal>}
function OrderEditModal({x,close,saved}:{x:any;close:()=>void;saved:()=>void}){const[qty,setQty]=useState(String(x.quantity)),[price,setPrice]=useState(String(Number(x.unit_price||0)/100)),[status,setStatus]=useState(x.status),[notes,setNotes]=useState(x.notes||'');return <Modal title="Siparişi düzenle" close={close}><FormGrid><Field label="Adet"><input type="number" value={qty} onChange={e=>setQty(e.target.value)}/></Field><Field label="Birim fiyat (TL)"><input type="number" value={price} onChange={e=>setPrice(e.target.value)}/></Field><Field label="Durum"><select value={status} onChange={e=>setStatus(e.target.value)}><option>ONAYLANDI</option><option>SIPARIS_LISTESINDE</option><option>B2B_SIPARISI_VERILDI</option><option>URUN_GELDI</option><option>TESLIM_EDILDI</option><option>IPTAL</option></select></Field><Field label="Not"><input value={notes} onChange={e=>setNotes(e.target.value)}/></Field></FormGrid><ModalActions close={close} save={async()=>{await api(`/api/orders/${x.id}`,{method:'PATCH',body:JSON.stringify({quantity:Number(qty),unit_price:Math.round(Number(price)*100),status,notes})});saved()}}/></Modal>}

